SELECT wp_wc_orders.id FROM wp_wc_orders INNER JOIN wp_wc_orders_meta AS meta0 ON ( wp_wc_orders.id = meta0.order_id ) INNER JOIN wp_wc_orders_meta AS meta1 ON ( wp_wc_orders.id = meta1.order_id ) WHERE 1=1 AND (wp_wc_orders.status IN ('wc-pending','wc-processing','wc-on-hold','wc-completed','wc-refunded','wc-checkout-draft')) AND (wp_wc_orders.type IN ('shop_order','shop_order_refund')) AND (wp_wc_orders.id NOT IN (11,17,19,20,21,… 691 ids)) AND (((meta0.meta_key = '_m1_marker') OR (meta1.meta_key = '_m2_marker'))) GROUP BY wp_wc_orders.id ORDER BY wp_wc_orders.date_created_gmt DESC LIMIT 0, 20

SELECT COUNT(DISTINCT wp_wc_orders.id) FROM wp_wc_orders INNER JOIN wp_wc_orders_meta AS meta0 ON ( wp_wc_orders.id = meta0.order_id ) INNER JOIN wp_wc_orders_meta AS meta1 ON ( wp_wc_orders.id = meta1.order_id ) WHERE 1=1 AND (wp_wc_orders.status IN ('wc-pending','wc-processing','wc-on-hold','wc-completed','wc-refunded','wc-checkout-draft')) AND (wp_wc_orders.type IN ('shop_order','shop_order_refund')) AND (wp_wc_orders.id NOT IN (11,17,19,20,21,… 691 ids)) AND (((meta0.meta_key = '_m1_marker') OR (meta1.meta_key = '_m2_marker')))
